<?php /**
 * Settings panel #project-directory ("Les projets"): links to every project, the current one
 * marked. Admins also get "Créer un projet" (opens #project-dialog) and per-project
 * "Modifier" buttons (data-edit-project: app.js fetches GET /projects/{id}/settings, which
 * renders project-settings.php). Admins can archive a project (POST /projects/{id}/archive): it then
 * leaves menus and selectors and is listed under "Projets archivés" with a "Réactiver" button.
 * Included by sections/settings.php. Expects $projects, $archivedProjects (admins only), $project and $user.
 */ ?>
<section class="panel" id="project-directory">
 <div class="panel-header"><div><h2>Les projets</h2><p>Un cap pour chaque initiative.</p></div></div>
 <?php if($user['role']==='admin'): ?><div class="settings-toolbar"><button class="button primary" data-open="project-dialog"><?= icon('plus') ?>Créer un projet</button></div><?php endif; ?>
 <?php foreach($projects as $p): ?><div class="settings-project-row"><a class="settings-project" href="/?project=<?= (int)$p['id'] ?>" <?= (int)$project['id']===(int)$p['id']?'aria-current="true"':'' ?>><?= project_mark($p,'tile') ?><div><strong><?= e($p['name']) ?></strong><small><?= e($p['description']) ?></small></div><?php if((int)$project['id']===(int)$p['id']): ?><span class="project-current">Sélectionné</span><?php endif; ?><?= icon('arrow') ?></a><?php if($user['role']==='admin'): ?><div class="settings-row-actions"><button type="button" class="button subtle" data-edit-project="<?= (int)$p['id'] ?>" aria-label="<?= e('Modifier le projet '.$p['name']) ?>"><?= icon('settings') ?>Modifier</button><?php if(count($projects)>1): ?><form method="post" action="/projects/<?= (int)$p['id'] ?>/archive" data-confirm="<?= e('Archiver le projet « '.$p['name'].' » ? Il n’apparaîtra plus dans les menus, les sélecteurs ni les listes « Tous les projets ». Ses tickets et ses réglages sont conservés et vous pourrez le réactiver ici.') ?>"><?= csrf() ?><input type="hidden" name="_return" value="/settings#project-directory"><input type="hidden" name="action" value="archive"><button class="button settings-danger" aria-label="<?= e('Archiver le projet '.$p['name']) ?>">Archiver</button></form><?php endif; ?></div><?php endif; ?></div><?php endforeach; ?>
 <?php if($user['role']==='admin' && !empty($archivedProjects)): ?><details class="project-archive"><summary>Projets archivés (<?= count($archivedProjects) ?>)</summary><p class="help-text">Ces projets n’apparaissent plus dans les menus, les sélecteurs ni les listes « Tous les projets ». Leurs données sont conservées et restent consultables par leur lien.</p>
 <?php foreach($archivedProjects as $p): ?><div class="settings-project-row is-archived"><a class="settings-project" href="/?project=<?= (int)$p['id'] ?>" <?= (int)$project['id']===(int)$p['id']?'aria-current="true"':'' ?>><?= project_mark($p,'tile') ?><div><strong><?= e($p['name']) ?></strong><small><?= e($p['description']) ?></small></div><span class="pill neutral">Archivé</span><?= icon('arrow') ?></a><div class="settings-row-actions"><form method="post" action="/projects/<?= (int)$p['id'] ?>/archive"><?= csrf() ?><input type="hidden" name="_return" value="/settings#project-directory"><input type="hidden" name="action" value="restore"><button class="button subtle" aria-label="<?= e('Réactiver le projet '.$p['name']) ?>">Réactiver</button></form></div></div><?php endforeach; ?></details><?php endif; ?>
</section>
